<?php

namespace App\Services\Locale;

use App\Services\Content\PathBuilder;
use Modules\BackEnd\Entities\AdLanguage;

/**
 * Last line of defence for public output generated by Laravel (phase 1C, greenruby-web docs/i18n-audit/phase-1/
 * 1c-report.md): whatever a query returned, nothing in a language that is not effectively public (LocaleRegistry)
 * leaves through a sitemap entry, an hreflang alternate or a Laravel-served public route.
 *
 * For en/vi this is a no-op by construction: both are always effectively public, so it only ever removes things.
 */
final class PublicLocaleGate
{
    /**
     * The language of a public URL or path, from its first path segment: a non-default language's URL prefix
     * (ad_language.url_prefix, or its code before the registry migration) selects it; anything else is the
     * default language, whose URLs have no prefix.
     */
    public static function languageOfUrl(string $url): ?AdLanguage
    {
        $path = parse_url($url, PHP_URL_PATH) ?? $url;
        $segment = strtolower(explode('/', ltrim((string) $path, '/'), 2)[0]);
        $default = LocaleRegistry::defaultLanguage();
        if ($segment !== '') {
            foreach (LocaleRegistry::all() as $language) {
                if ($default && (int) $language->id === (int) $default->id) {
                    continue;
                }
                if ($segment === strtolower((string) ($language->getAttribute('url_prefix') ?: $language->code))) {
                    return $language;
                }
            }
        }

        return $default;
    }

    public static function isPublicCode(?string $code): bool
    {
        $language = LocaleRegistry::byCode($code);

        return $language !== null && LocaleRegistry::isEffectivePublic($language);
    }

    /** en/vi: their alternates come from Laravel's builders; intl alternates only from IntlSitemap (1C-5). */
    private static function isLegacyCode(string $code): bool
    {
        $language = LocaleRegistry::byCode($code);

        return $language !== null && LocaleRegistry::isLegacy($language);
    }

    public static function isPublicUrl(string $url): bool
    {
        $language = self::languageOfUrl($url);
        if ($language === null || !LocaleRegistry::isEffectivePublic($language)) {
            return false;
        }
        // Phase 1C-3: an intl row without a slug has no URL (its Laravel route renders "/-{id}.html").
        $file = basename((string) (parse_url($url, PHP_URL_PATH) ?? ''));

        return LocaleRegistry::isLegacy($language) || !str_starts_with($file, '-');
    }

    /**
     * Sitemap entries ({loc, alternates: [{hreflang, url}]}): drops entries whose URL is in a non-public language
     * and alternates pointing to one. x-default follows the existing rule (FeHreflangUtils: only next to at least
     * two language links), so it is removed when filtering leaves a single language.
     */
    public static function sitemapEntries(array $entries, ?string $kind = null): array
    {
        $kept = [];
        foreach ($entries as $entry) {
            if (!self::isPublicUrl((string) ($entry['loc'] ?? ''))) {
                continue;
            }
            // Phase 1C-5: intl-language entries come only from IntlSitemap, never from Laravel's shared routes.
            $language = self::languageOfUrl((string) $entry['loc']);
            if ($language && !LocaleRegistry::isLegacy($language)) {
                continue;
            }
            if (!empty($entry['alternates']) && is_array($entry['alternates'])) {
                $entry['alternates'] = self::alternates($entry['alternates']);
            }
            $kept[] = self::normalizeIntl($entry);
        }

        $intl = $kind === null ? [] : IntlSitemap::entries($kind);

        return $intl === [] ? $kept : self::withIntl($kept, $intl);
    }

    /**
     * Adds intl entries and makes hreflang reciprocal: every member of a translation group (detail page or section
     * hub) carries exactly the same alternates list — the TranslationResolver's for details, the existing EN/VI hub
     * list plus the intl hubs for hubs.
     */
    private static function withIntl(array $kept, array $intl): array
    {
        $path = fn (string $url) => (string) (parse_url($url, PHP_URL_PATH) ?? $url);
        $setAlternates = function (array $urls, array $alternates) use (&$kept, $path) {
            $paths = array_map($path, $urls);
            foreach ($kept as $i => $entry) {
                if (in_array($path((string) $entry['loc']), $paths, true)) {
                    $kept[$i]['alternates'] = $alternates;
                }
            }
        };

        $hubs = [];
        foreach ($intl as $entry) {
            if (str_starts_with($entry['group'], 'hub:')) {
                $hubs[substr($entry['group'], 4)][] = $entry;
                continue;
            }
            $members = array_column(array_filter($entry['alternates'], fn ($a) => $a['hreflang'] !== 'x-default'), 'url');
            if ($members !== []) {
                $setAlternates($members, $entry['alternates']);
            }
        }

        foreach ($hubs as $section => $intlHubs) {
            $legacyUrls = [];
            foreach (LocaleRegistry::effectivePublic()->filter(fn ($l) => LocaleRegistry::isLegacy($l)) as $legacy) {
                $legacyUrls[$legacy->code] = $section === 'home' ? PathBuilder::home($legacy) : PathBuilder::section($legacy, $section);
            }
            $base = [];
            foreach ($kept as $entry) {
                if (in_array($path((string) $entry['loc']), $legacyUrls, true) && !empty($entry['alternates'])) {
                    $base = $entry['alternates'];
                    break;
                }
            }
            $languages = array_values(array_filter($base, fn ($a) => $a['hreflang'] !== 'x-default'));
            $xDefault = array_values(array_filter($base, fn ($a) => $a['hreflang'] === 'x-default'));
            foreach ($intlHubs as $hub) {
                $languages[] = ['hreflang' => self::hreflangOf($hub['loc']), 'url' => $hub['loc']];
            }
            $alternates = count($languages) >= 2 ? array_merge($languages, $xDefault) : [];
            $setAlternates(array_column($languages, 'url'), $alternates);
            foreach ($intlHubs as $i => $hub) {
                $intlHubs[$i]['alternates'] = $alternates;
            }
            $hubs[$section] = $intlHubs;
        }

        $added = [];
        foreach ($intl as $entry) {
            if (str_starts_with($entry['group'], 'hub:')) {
                continue;
            }
            unset($entry['group']);
            $added[] = $entry;
        }
        foreach ($hubs as $intlHubs) {
            foreach ($intlHubs as $hub) {
                unset($hub['group']);
                $added[] = $hub;
            }
        }

        return array_merge($kept, $added);
    }

    private static function hreflangOf(string $url): string
    {
        $language = self::languageOfUrl($url);

        return (string) ($language?->getAttribute('hreflang') ?: $language?->code);
    }

    /**
     * Phase 1C-3: URLs of an intl language take PathBuilder's form (English segments under the prefix) instead of
     * the Vietnamese segments of Laravel's shared multi-language routes. en/vi URLs are never rewritten.
     */
    private static function normalizeIntl(array $entry): array
    {
        $fix = function (string $url): string {
            $language = self::languageOfUrl($url);
            if (!$language || LocaleRegistry::isLegacy($language)) {
                return $url;
            }
            $parts = parse_url($url);
            $path = $parts['path'] ?? '/';
            $normalized = PathBuilder::normalizeIntlPath($path, $language);

            return $normalized === $path ? $url : substr($url, 0, strlen($url) - strlen($path) - (isset($parts['query']) ? strlen($parts['query']) + 1 : 0)) . $normalized . (isset($parts['query']) ? '?' . $parts['query'] : '');
        };
        $entry['loc'] = $fix((string) $entry['loc']);
        foreach ($entry['alternates'] ?? [] as $i => $alternate) {
            $entry['alternates'][$i]['url'] = $fix((string) $alternate['url']);
        }

        return $entry;
    }

    /** @param array<int, array{hreflang: string, url: string}> $alternates */
    public static function alternates(array $alternates): array
    {
        $languages = [];
        $xDefault = [];
        $dropped = 0;
        foreach ($alternates as $alternate) {
            $code = (string) ($alternate['hreflang'] ?? '');
            if ($code === 'x-default') {
                $xDefault[] = $alternate;
            } elseif (self::isPublicCode($code) && self::isLegacyCode($code) && self::isPublicUrl((string) ($alternate['url'] ?? ''))) {
                $languages[] = $alternate;
            } else {
                $dropped++;
            }
        }
        if ($dropped === 0) {
            return $alternates; // nothing to hide: the original list, order included
        }
        if (count($languages) < 2) {
            return $languages;
        }
        // x-default may only point at a URL that is itself still listed.
        $listed = array_column($languages, 'url');
        $xDefault = array_values(array_filter($xDefault, fn ($a) => in_array($a['url'] ?? null, $listed, true)));

        return array_merge($languages, $xDefault);
    }
}
